    /// <summary>Enumerate a directory tree, filtered by pattern, and return a list.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GlobStorageDirectory</c>.</para>
    /// <para>
    /// Files are filtered out if they don't match the string in <c>pattern</c>, which may contain wildcard characters
    /// <c>*</c> (match everything) and <c>?</c> (match one character). If pattern is NULL, no filtering is done and all
    /// results are returned. Subdirectories are permitted, and are specified with a path separator of '/'. Wildcard
    /// characters <c>*</c> and <c>?</c> never match a path separator.
    /// </para>
    /// <para><c>flags</c> may be set to SDL_GLOB_CASEINSENSITIVE to make the pattern matching case-insensitive.</para>
    /// <para>
    /// The returned array is always NULL-terminated, for your iterating convenience, but if <c>count</c> is non-NULL,
    /// on return it will contain the number of items in the array, not counting the NULL terminator.
    /// </para>
    /// <para>
    /// If <c>path</c> is NULL, this is treated as a request to enumerate the root of the storage container's tree. An
    /// empty string also works for this.
    /// </para>
    /// <para>
    /// Thread safety: It is safe to call this function from any thread, assuming the <c>storage</c> object is
    /// thread-safe.
    /// </para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="storage">a storage container.</param>
    /// <param name="path">the path of the directory to enumerate, or NULL for the root.</param>
    /// <param name="pattern">the pattern that files in the directory must match. Can be NULL.</param>
    /// <param name="flags"><c>SDL_GLOB_*</c> bitflags that affect this search.</param>
    /// <param name="count">on return, will be set to the number of items in the returned array. Can be NULL.</param>
    /// <returns>
    /// an array of strings on success or NULL on failure; call SDL_GetError() for more information. The caller should
    /// pass the returned pointer to SDL_free when done with it. This is a single allocation that should be freed with
    /// SDL_free() when it is no longer needed.
    /// </returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_GlobStorageDirectory")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial byte** GlobStorageDirectory(Storage storage, byte* path, byte* pattern, GlobFlags flags, int* count);

